export function calculateEntropy(probabilities) {
  if (!Array.isArray(probabilities) || probabilities.some(p => p < 0 || p > 1)) {
    throw new Error('Invalid probabilities array.');
  }
  return -probabilities.reduce((total, p) => total + (p > 0 ? p * Math.log2(p) : 0), 0);
}

export function evaluateRecursiveChanges(changes) {
  const probabilities = changes.map(change => change.confidence);
  const entropy = calculateEntropy(probabilities);
  return entropy < 1.5 ? 'Stable' : 'Unstable';
}